mapper.sql:

WHERE TRUE

    AND ${alias}.${@com.lingan.ucp.nocode.runtime.dal.support.RuntimeSqlParameters@quote('deleted')}::text IN ('0','false')


    AND ${alias}.${@com.lingan.ucp.nocode.runtime.dal.support.RuntimeSqlParameters@quote(_record.keyColumn)}::text = #{${prefix}id}


    AND ${alias}.${@com.lingan.ucp.nocode.runtime.dal.support.RuntimeSqlParameters@quote(_record.parentColumn)}::text = #{${prefix}parentId}


    AND ${alias}.${@com.lingan.ucp.nocode.runtime.dal.support.RuntimeSqlParameters@quote('creator')} = #{${prefix}creator}



    AND EXISTS (
    SELECT 1
    FROM ${@com.lingan.ucp.nocode.runtime.dal.support.RuntimeSqlParameters@quote(_scope.schema)}.${@com.lingan.ucp.nocode.runtime.dal.support.RuntimeSqlParameters@quote(_scope.table)} link
    WHERE link.deleted = 0
    AND link.${@com.lingan.ucp.nocode.runtime.dal.support.RuntimeSqlParameters@quote(_scope.matchingColumn)}::text = ${alias}.${@com.lingan.ucp.nocode.runtime.dal.support.RuntimeSqlParameters@quote(_record.keyColumn)}::text
    AND link.${@com.lingan.ucp.nocode.runtime.dal.support.RuntimeSqlParameters@quote(_scope.contextColumn)}::text = #{${prefix}relationScope.contextId}
    )


    AND ${alias}.${@com.lingan.ucp.nocode.runtime.dal.support.RuntimeSqlParameters@quote(_conditionColumn)} IS NOT DISTINCT FROM (
    jsonb_populate_record(NULL::

    , CAST(#{${prefix}filters} AS jsonb))
    ).${@com.lingan.ucp.nocode.runtime.dal.support.RuntimeSqlParameters@quote(_conditionColumn)}


    AND (

        ${alias}.${@com.lingan.ucp.nocode.runtime.dal.support.RuntimeSqlParameters@quote(_conditionColumn)}::text ILIKE #{${prefix}search} ESCAPE '!'

    )





    AND (${_record.dynamicQuery.sqlSegment.replace('t.', _alias).replace('#{', '#{' + _parameterPrefix)})





    AND (${_record.dashboardScope.sql.replace('__dashboard_outer__.', _dashboardAlias).replace('#{', '#{' + _dashboardPrefix)})

mapper.select:
SELECT jsonb_build_object(
    'parent', ${@com.lingan.ucp.nocode.runtime.dal.support.RuntimeSqlParameters@quote(parentColumn)}::text,
    'value', ${operation.name()}(

    *
    ${@com.lingan.ucp.nocode.runtime.dal.support.RuntimeSqlParameters@quote(column)}

)::text
)::text
FROM ${@com.lingan.ucp.nocode.runtime.dal.support.RuntimeSqlParameters@quote(schema)}.${@com.lingan.ucp.nocode.runtime.dal.support.RuntimeSqlParameters@quote(table)}
WHERE ${@com.lingan.ucp.nocode.runtime.dal.support.RuntimeSqlParameters@quote(parentColumn)}::text IN (
SELECT jsonb_array_elements_text(CAST(#{parents} AS jsonb))
)
AND deleted::text IN ('0','false')
GROUP BY ${@com.lingan.ucp.nocode.runtime.dal.support.RuntimeSqlParameters@quote(parentColumn)}

mapper.update:
UPDATE



SET deleted = 1, updater = #{actor}, update_time = clock_timestamp()
WHERE deleted = 0 AND source_id::text = #{sourceId}
AND target_id::text = #{targetId}

mapper.sql:

WHERE t.${@com.lingan.ucp.nocode.runtime.dal.support.RuntimeSqlParameters@quote(keyColumn)} = (
    jsonb_populate_record(NULL::
    ,
    jsonb_build_object(CAST(#{keyColumn} AS text), CAST(#{id} AS text)))
).${@com.lingan.ucp.nocode.runtime.dal.support.RuntimeSqlParameters@quote(keyColumn)}

    AND t.${@com.lingan.ucp.nocode.runtime.dal.support.RuntimeSqlParameters@quote('deleted')}::text IN ('0','false')

mapper.select:
SELECT jsonb_build_object('values', group_values, 'rows', count(*),
    'nullRows', count(*) FILTER (WHERE missing_value))::text
FROM (
    SELECT jsonb_build_array(

            t.${@com.lingan.ucp.nocode.runtime.dal.support.RuntimeSqlParameters@quote(column)}

    ) AS group_values,
    t.${@com.lingan.ucp.nocode.runtime.dal.support.RuntimeSqlParameters@quote(outputColumn)} IS NULL AS missing_value
    FROM  t






) grouped GROUP BY group_values ORDER BY group_values

, calculated AS ( SELECT t.${@com.lingan.ucp.nocode.runtime.dal.support.RuntimeSqlParameters@quote(record.keyColumn)}::text AS calculation_id,
LEAD(to_jsonb(t)) OVER calculation_order LAG(to_jsonb(t)) OVER calculation_order AS sequence_values FROM calculation_source t
WINDOW calculation_order AS ( ORDER BY
t.${@com.lingan.ucp.nocode.runtime.dal.support.RuntimeSqlParameters@quote(orderColumn)} ASC NULLS LAST
) ) SELECT sequence_values::text FROM calculated WHERE calculation_id = #{rowId}
